example.code:
// Create a call profile
var profile = new CallProfile(
    new CallProfile.Skill(101, level: 3, mandatory: true),
    new CallProfile.Skill(102, level: 2, mandatory: false)
);

// Access a skill by number
CallProfile.Skill skill = profile.Get(101);

// Check if a skill exists
bool hasSkill = profile.Contains(102);

// Iterate over all skills
foreach (CallProfile.Skill s in profile.Skills)
    Console.WriteLine($"{s.Number}: level {s.Level}");

// Pass to a telephony call
await telephony.MakePilotOrRSICallAsync(deviceId, pilot, callProfile: profile);

var params = new PilotTransferQueryParameters()
    .SetAgentNumber("1234")
    .SetPriorityTransfer(true)
    .SetCallProfile(profile);

// Attach correlator data to a call
var data = new CorrelatorData("transactionId=abc123");
await telephony.MakeCallAsync("1234", "5678", autoAnswer: true, correlatorData: data);

// Read correlator data from a received call event
telephony.CallCreated += (sender, e) =>
{
    var correlator = e.Event.CallData?.CorrelatorData;
    if (correlator != null)
    {
        Console.WriteLine($"Context: {correlator.AsString()}");
    }
};

